root=pathlib.Path('/private/tmp/encoder-recon-fusion-20261018/output-v1-screen')
root.mkdir(exist_ok=True)
base='/private/tmp/encoder-recon-fusion-20261018/qualitybench-baseline'
candidate='/private/tmp/encoder-recon-fusion-20261018/qualitybench-output-v1'
corpus=pathlib.Path('/private/tmp/claude-501/-Users-thesyncim-GolandProjects-goav1/762709d9-4fbe-4108-a0ab-525265dc00ac/scratchpad/enc')
control=pathlib.Path('/private/tmp/encoder-context-gap-20261018/FourPeople-8.yuv')
cases=[('FourPeople',3000000,str(corpus/'FourPeople.yuv'),120,0),('Johnny',9000000,str(corpus/'Johnny.yuv'),120,0)]
env=dict(os.environ,GOMAXPROCS='1',GOGC='100',GOEXPERIMENT='simd')
rows=[]
expected={'FourPeople':'37130ff37d12dee5c5279de42b51aa86ef25f17073a78bdd842c4402d88b2c67','Johnny':'b1140a4c298f975c1d6330e2d72e62276fc184c1926e36e8129e00499a0963c5','FourPeople-key-control':'43f9c04111eb911ecdbe893659380117553fee0b736d9839e943cd6b91a0006f'}
def run(case, variant, phase, pair):
 name,bps,input_,frames,keyint=case
 path=root/f'{phase}-{name}-{pair}-{variant}';path.mkdir()
 args=[base if variant=='baseline' else candidate,'__qualitybench_goav1_encode','-width','1280','-height','720','-frames',str(frames),'-fps','60','-input',input_,'-workdir',str(path),'-bitrate',str(bps),'-layers','1','-tiles','0','-golden','0','-keyint',str(keyint),'-gomaxprocs','1','-gogc','100','-goav1-max-threads','1','-goav1-effort','0','-goav1-scene-cut=true','-stats-enabled=false','-frame-stats-enabled=false','-result-json',str(path/'result.json')]
 before=resource.getrusage(resource.RUSAGE_CHILDREN);start=time.perf_counter()
 with open(path/'stderr.log','w') as log: p=subprocess.run(args,env=env,stdout=log,stderr=log)
 wall=time.perf_counter()-start;after=resource.getrusage(resource.RUSAGE_CHILDREN)
 result=json.loads((path/'result.json').read_text())
 row={'phase':phase,'case':name,'pair':pair,'variant':variant,'wall':wall,'user':after.ru_utime-before.ru_utime,'sys':after.ru_stime-before.ru_stime,'status':result['status'],'returncode':p.returncode,'sha256':result['encoded_sha256'],'bytes':result['encoded_bytes'],'command':args}
 rows.append(row)
 (root/'screen-raw.json').write_text(json.dumps(rows,indent=2)+'\n')
 print(json.dumps({k:v for k,v in row.items() if k!='command'}),flush=True)
 assert p.returncode==0 and result['status']=='ok'
 if name in expected: assert row['sha256']==expected[name],(name,row['sha256'])
for case in cases:
 for variant in ['baseline','candidate']:run(case,variant,'warmup',0)
for pair in range(1,4):
 for case in cases:
  for variant in (['baseline','candidate'] if pair%2 else ['candidate','baseline']):run(case,variant,'sample',pair)
key=('FourPeople-key-control',3000000,str(control),8,1)
for variant in ['candidate','baseline']:run(key,variant,'control',1)
summary={}
for name in [c[0] for c in cases]+[key[0]]:
 rs=[r for r in rows if r['case']==name and r['phase']!='warmup']
 groups={v:[r for r in rs if r['variant']==v] for v in ['baseline','candidate']}
 ratios=[c['wall']/b['wall'] for b,c in zip(groups['baseline'],groups['candidate'])]
 cpu_ratios=[(c['user']+c['sys'])/(b['user']+b['sys']) for b,c in zip(groups['baseline'],groups['candidate'])]
 assert len(set(r['sha256'] for r in rs))==1
 summary[name]={'baseline_wall_median':statistics.median(r['wall'] for r in groups['baseline']),'candidate_wall_median':statistics.median(r['wall'] for r in groups['candidate']),'paired_saving_pct':[100*(1-r) for r in ratios],'paired_geomean_saving_pct':100*(1-math.exp(sum(math.log(r) for r in ratios)/len(ratios))),'paired_cpu_saving_pct':[100*(1-r) for r in cpu_ratios],'paired_geomean_cpu_saving_pct':100*(1-math.exp(sum(math.log(r) for r in cpu_ratios)/len(cpu_ratios))),'sha256':rs[0]['sha256'],'bytes':rs[0]['bytes']}
(root/'screen-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
print(json.dumps(summary,indent=2))

