package main

import (
 "crypto/sha256"
 "encoding/binary"
 "encoding/hex"
 "encoding/json"
 "fmt"
 "os"
 goav1 "github.com/thesyncim/goav1"
)

type result struct { Layers int; Bytes int; Bitstream, Recon string; Keys, Temporal []uint8 }
func main() {
 results := []result{}
 for _, layers := range []int{1,2} {
  const w,h = 192,128
  enc,err := goav1.NewVideoEncoder(goav1.VideoEncoderConfig{Width:w,Height:h,TargetBitrate:500000,Framerate:60,MaxThreads:1,TemporalLayers:layers,DisableSceneCutKeyframes:true})
  if err!=nil { panic(err) }
  bs,rec:=sha256.New(),sha256.New()
  r:=result{Layers:layers}
  for n:=0;n<20;n++ {
   f:=goav1.I420Frame{Y:make([]byte,w*h),U:make([]byte,w*h/4),V:make([]byte,w*h/4),YStride:w,ChromaStride:w/2,Width:w,Height:h}
   for y:=0;y<h;y++ { for x:=0;x<w;x++ { xx:=(x+n*3)%w; f.Y[y*w+x]=byte(30+(xx/3+y/2)%130+(xx*y%17)) } }
   for y:=0;y<h/2;y++ { for x:=0;x<w/2;x++ { f.U[y*w/2+x]=byte(100+(x+n*2+y)%45); f.V[y*w/2+x]=byte(110+(x/2-y+n+40)%45) } }
   out,err:=enc.Encode(f,n==11); if err!=nil { panic(err) }
   var size [8]byte; binary.LittleEndian.PutUint64(size[:],uint64(len(out.Data))); bs.Write(size[:]);bs.Write(out.Data)
   r.Bytes+=len(out.Data); if out.Keyframe { r.Keys=append(r.Keys,uint8(n)) };r.Temporal=append(r.Temporal,out.TemporalID)
   recon:=enc.Reconstruction();rec.Write(recon.Y);rec.Write(recon.U);rec.Write(recon.V)
  }
  r.Bitstream=hex.EncodeToString(bs.Sum(nil));r.Recon=hex.EncodeToString(rec.Sum(nil));results=append(results,r)
  if err:=enc.Close();err!=nil{panic(err)}
 }
 data,err:=json.MarshalIndent(results,"","  ");if err!=nil{panic(err)};fmt.Fprintln(os.Stdout,string(data))
}
